package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;

/** The figures a claim has: live, fixed when settled, or bound by a statement. */
public final class ClaimDue {

    private ClaimDue() {
    }

    /** Whether a claim counts toward claimed and the totals: only OPEN and SETTLED claims do. */
    public static boolean counts(Claim claim) {
        return claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.SETTLED;
    }

    /** Whether a claim counts toward the live totals (claimed, due-totals, a period's due-total): one that counts,
     *  unless it is OPEN and its person is on hold. */
    public static boolean countsLive(Claim claim, boolean held) {
        return counts(claim) && !(held && claim.status() == ClaimStatus.OPEN);
    }

    /** The claim's amount at the grade's rate in force on its date, rounded half to even to two decimals, and at
     *  least the sheet's floor (a correction has no floor); null when no rate applies. */
    public static BigDecimal live(Claim claim, String grade, RateRepository rates, BigDecimal floor) {
        Rate rate = rates.find(claim.sheetId(), grade, claim.date());
        if (rate == null) {
            return null;
        }
        BigDecimal due = claim.amount().multiply(rate.rate()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
        return isCorrection(claim) ? due : due.max(floor);
    }

    /** Whether the claim is a correction: its amount is negative. */
    public static boolean isCorrection(Claim claim) {
        return claim.amount().signum() < 0;
    }

    /** The figure the claim shows: fixed when settled, else the one a statement bound it to, else live; null when
     *  it has none (n/a). */
    public static BigDecimal figure(Claim claim, String grade, RateRepository rates, BigDecimal floor) {
        if (claim.due() != null) {
            return claim.due();
        }
        return claim.stated() ? claim.statedDue() : live(claim, grade, rates, floor);
    }

    /** Whether the claim keeps a figure whatever the rates are: fixed when settled, or bound by a statement. */
    public static boolean kept(Claim claim) {
        return claim.due() != null || (claim.stated() && claim.statedDue() != null);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/**
 * The late charge on a sheet as of its today: an overdue claim (OPEN, its due-by — its date plus the terms — before
 * today) gains the late percent of its figure for every full 30 days it is overdue, rounded half to even to two
 * decimals. The charge is never bound by a statement (it follows today); settling freezes it into the claim's due.
 */
public record LateCharge(LocalDate today, int terms, BigDecimal pct) {

    /** The days in each step of the charge. */
    public static final int DAYS = 30;

    public static LateCharge of(String sheetId, SheetRepository sheets, SettingRepository settings) {
        return new LateCharge(sheets.today(sheetId), settings.terms(sheetId), settings.latePct(sheetId));
    }

    /** The charge on the claim with the given figure: zero when it is not overdue a full 30 days, has no figure, or
     *  is a correction. */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        if (figure == null || claim.status() != ClaimStatus.OPEN || claim.due() != null || ClaimDue.isCorrection(claim)) {
            return BigDecimal.ZERO.setScale(2);
        }
        long overdue = ChronoUnit.DAYS.between(claim.date().plusDays(terms), today);
        long steps = overdue <= 0 ? 0 : overdue / DAYS;
        return figure.multiply(pct).multiply(BigDecimal.valueOf(steps)).movePointLeft(2)
                .setScale(2, RoundingMode.HALF_EVEN);
    }

    /** The figure with its charge added on top; null when it has none. */
    public BigDecimal add(Claim claim, BigDecimal figure) {
        return figure == null ? null : figure.add(on(claim, figure));
    }
}
package net.officefloor.hq.app.claim;

/**
 * A claim with a negative amount is a correction: allowed only when it names, by number, a SETTLED claim of the same
 * person that it corrects. Any other claim corrects nothing (a number given with it is not kept).
 */
public final class Corrections {

    private Corrections() {
    }

    /** The number the claim with these values corrects (null when it is not a correction); a correction that does
     *  not name a SETTLED claim of the person is refused. */
    public static Long check(String sheetId, long personId, ClaimValues values, ClaimRepository claims)
            throws InvalidClaimException {
        if (values.amount().signum() >= 0) {
            return null;
        }
        if (values.corrects() == null) {
            throw new InvalidClaimException("A negative amount must name the settled claim it corrects");
        }
        Claim corrected = claims.findByNumber(sheetId, personId, values.corrects());
        if (corrected == null || corrected.status() != ClaimStatus.SETTLED) {
            throw new InvalidClaimException("A correction must name a settled claim of the same person");
        }
        return values.corrects();
    }
}
